CREATE TABLE IF NOT EXISTS archive_catalog_revision (id TEXT PRIMARY KEY, revision INTEGER NOT NULL);
INSERT OR IGNORE INTO archive_catalog_revision VALUES('catalog',1);
CREATE INDEX IF NOT EXISTS archive_imports_state ON archive_imports(state);
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_videos_insert AFTER INSERT ON archive_videos BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_videos_update AFTER UPDATE ON archive_videos BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_videos_delete AFTER DELETE ON archive_videos BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_links_insert AFTER INSERT ON archive_links BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_links_update AFTER UPDATE ON archive_links BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_links_delete AFTER DELETE ON archive_links BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_client_directory_insert AFTER INSERT ON client_directory BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_client_directory_update AFTER UPDATE ON client_directory BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_client_directory_delete AFTER DELETE ON client_directory BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_client_edits_insert AFTER INSERT ON archive_client_edits BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_client_edits_update AFTER UPDATE ON archive_client_edits BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_archive_client_edits_delete AFTER DELETE ON archive_client_edits BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_mux_library_snapshot_state_insert AFTER INSERT ON mux_library_snapshot_state BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_mux_library_snapshot_state_update AFTER UPDATE ON mux_library_snapshot_state BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_mux_library_snapshot_state_delete AFTER DELETE ON mux_library_snapshot_state BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_active_scan AFTER UPDATE OF active_scan ON archive_state WHEN NEW.active_scan IS NOT OLD.active_scan BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_files_insert AFTER INSERT ON archive_files WHEN NEW.scan_id=(SELECT active_scan FROM archive_state WHERE id='archive') BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_files_update AFTER UPDATE ON archive_files WHEN NEW.scan_id=(SELECT active_scan FROM archive_state WHERE id='archive') BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
CREATE TRIGGER IF NOT EXISTS archive_revision_files_delete AFTER DELETE ON archive_files WHEN OLD.scan_id=(SELECT active_scan FROM archive_state WHERE id='archive') BEGIN UPDATE archive_catalog_revision SET revision=revision+1 WHERE id='catalog'; END;
